def test_update_can_scale_down_across_candidates_in_one_recompute(self):
    params = self._make_params_from_config(
        7,
        {
            "candidate_steps": [1, 3, 7],
            "ema_alpha": 1.0,
            "warmup_batches": 0,
            "update_interval": 1,
        },
    )

    self.assertTrue(params.update([0, 0]))
    self.assertEqual(params.current_steps, 1)

